/* GwDao.updateFaultReports */
UPDATE 	TB_FAC_FAULT_RPT
SET 	OVERALL_AVAIL_CD = #{overallAvailCd} 
		, PROGRESS_CD = #{progressCd} 
		, BREAK_HOUR_YN = #{breakHourYn} 
		, BREAK_HOUR = #{breakHour} 
		, EXPECT_HOUR_YN = #{expectHourYn} 
		, EXPECT_HOUR = #{expectHour} 
		, EXPECT_UNKNOWN_YN = #{expectUnknownYn} 
WHERE 	FACT_CD = #{factCd}

mapper.insert:
/* GwDao.upsertEquipGrpList */ INSERT INTO TB_FAC_FAULT_RPT_EQUIP (FACT_CD, EQUIP_GRP_CD, AVAIL_CD) VALUES
(#{factCd}, #{item.equipGrpCd}, #{item.availCd})
ON DUPLICATE KEY UPDATE AVAIL_CD = VALUES(AVAIL_CD)
